// =====================================================================
// Resumo da promocao. NENHUMA chamada de API foi feita neste fluxo --
// e' tudo JOIN entre rf_os e NF, dentro do banco.
// =====================================================================

const r = $input.first().json || {};

const antigos = Number(r.pendentes_ha_mais_de_3_dias || 0);

return [{
  json: {
    custo_api: 'ZERO - fluxo 100% SQL',
    rf_os_total: Number(r.rf_os_total || 0),
    promovidos: Number(r.promovidos || 0),
    ainda_sem_nota: Number(r.ainda_sem_nota || 0),
    vinculos_da_esteira: Number(r.vinculos_da_esteira || 0),
    rf_nota_total: Number(r.rf_nota_total || 0),

    pendentes_ha_mais_de_3_dias: antigos,
    alerta: antigos > 0
      ? antigos + ' RF(s) esperam nota ha mais de 3 dias. Ou a OS nao foi faturada '
        + '(cFaturada = N, e ai esta correto), ou a nota foi cancelada antes do fluxo '
        + 'diario passar (a nota nunca entra na NF quando cancelada) -- nesse segundo '
        + 'caso o RF esta desprotegido. Conferir na Omie.'
      : 'nenhuma pendencia antiga',

    conferir:
      "SELECT rf, cNumOs, criado_em FROM kvm4_db.rf_os WHERE promovido_em IS NULL ORDER BY criado_em",
  },
}];
